    "Manual annotations. No call to AI": ["人工标注，未调用 AI", "Anotaciones manuales, sin usar IA", "Manuelle Markierungen, ohne KI-Aufruf"],
    "Laptop": ["笔记本电脑", "Ordenador portátil", "Laptop"],
